    @Test
    fun ofInvoiceCostDataExportedRoundtrip() {
        val jsonMapper = jsonMapper()
        val unwrapStandardWebhookEvent =
            UnwrapStandardWebhookEvent.ofInvoiceCostDataExported(
                InvoiceCostDataExportedStandardWebhookEvent.builder()
                    .id("id")
                    .createdAt(OffsetDateTime.parse("2019-12-27T18:11:19.117Z"))
                    .invoice("invoice")
                    .payloadStyle(InvoiceCostDataExportedStandardWebhookEvent.PayloadStyle.EXPANDED)
                    .properties(
                        InvoiceCostDataExportedStandardWebhookEvent.Properties.builder()
                            .exportedDate(OffsetDateTime.parse("2019-12-27T18:11:19.117Z"))
                            .s3Bucket("s3_bucket")
                            .s3Key("s3_key")
                            .build()
                    )
                    .type(
                        InvoiceCostDataExportedStandardWebhookEvent.Type.INVOICE_COST_DATA_EXPORTED
                    )
                    .build()
            )

        val roundtrippedUnwrapStandardWebhookEvent =
            jsonMapper.readValue(
                jsonMapper.writeValueAsString(unwrapStandardWebhookEvent),
                jacksonTypeRef<UnwrapStandardWebhookEvent>(),
            )

        assertThat(roundtrippedUnwrapStandardWebhookEvent).isEqualTo(unwrapStandardWebhookEvent)
    }

